def transform(grid):
    n = len(grid)
    m = len(grid[0])
    out = [[7] * m for _ in range(n)]
    candidates = [v for v in set(x for row in grid for x in row) if v not in (0, 7)]
    color = None
    for v in candidates:
        cells = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == v]
        if cells and min(r for r, c in cells) == 0:
            color = v
            break
    if color is None:
        return out
    cells = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == color]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    size = min(r1 - r0 + 1, c1 - c0 + 1)
    average_c = sum(c for r, c in cells) / len(cells)
    if average_c - c0 <= c1 - average_c:
        for i in range(size):
            out[r0 + i][c0 + i] = color
    else:
        for i in range(size):
            out[r0 + i][c1 - i] = color
    return out
